import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { issueToken, verifyToken } from '../src/tokens.js';
test('a fresh token verifies to its user', () => {
  const db = createDb();
  const t = issueToken(db, 'u1', 1000);
  expect(typeof t).toBe('string');
  expect(verifyToken(db, t, 2000)).toBe('u1');
});
test('tokens differ between calls and unknown tokens are rejected', () => {
  const db = createDb();
  expect(issueToken(db, 'u1', 0)).not.toBe(issueToken(db, 'u1', 0));
  expect(verifyToken(db, 'nope', 0)).toBeNull();
});
test('a token stops working after one hour', () => {
  const db = createDb();
  const t = issueToken(db, 'u1', 0);
  expect(verifyToken(db, t, 59 * 60_000)).toBe('u1');
  expect(verifyToken(db, t, 61 * 60_000)).toBeNull();
});

