import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { issueToken, verifyToken } from '../src/tokens.js';
const dump = (db) => JSON.stringify(db, (k, v) => (v instanceof Map ? [...v] : v));
test('the raw token is never stored', () => {
  const db = createDb();
  const t = issueToken(db, 'u1', 0);
  expect(t.length).toBeGreaterThanOrEqual(32);
  expect(dump(db)).not.toContain(t);
  expect(verifyToken(db, t, 1)).toBe('u1');
});
test('wrong-length, truncated, extended and non-string values are rejected without throwing', () => {
  const db = createDb();
  const t = issueToken(db, 'u1', 0);
  for (const bad of ['', 'x', t.slice(0, -1), t + 'x', t.slice(0, 8), t.toUpperCase() === t ? t.toLowerCase() : t.toUpperCase(), undefined, null, 12345, {}, [t]]) {
    expect(() => verifyToken(db, bad, 1)).not.toThrow();
    expect(verifyToken(db, bad, 1)).toBeNull();
  }
  expect(verifyToken(db, t, 1)).toBe('u1');
});
